{"Table":"bk_tb_accounts","Create Table":"CREATE TABLE `bk_tb_accounts` (\n  `id` varchar(36) NOT NULL,\n  `name` varchar(255) NOT NULL,\n  `ammount` double NOT NULL,\n  `paymentType` varchar(255) NOT NULL,\n  `owner` varchar(255) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `threshold` double NOT NULL,\n  PRIMARY KEY (`id`),\n  KEY `FK_account_owner` (`owner`),\n  KEY `FK_account_payment_type` (`paymentType`),\n  CONSTRAINT `FK_account_owner` FOREIGN KEY (`owner`) REFERENCES `bk_tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `FK_account_payment_type` FOREIGN KEY (`paymentType`) REFERENCES `bk_tb_payments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"bk_tb_accounts.sql","path":"files/sql/rod/bk_tb_accounts.sql","sha":"71f4729898dea7ec6e6f53e1fd26c1b6958969b5","size":1316883,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/bk_tb_accounts.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/bk_tb_accounts.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/71f4729898dea7ec6e6f53e1fd26c1b6958969b5","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/bk_tb_accounts.sql","type":"file","content":"","encoding":"none","_links":{"self":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/bk_tb_accounts.sql?ref=master","git":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/71f4729898dea7ec6e6f53e1fd26c1b6958969b5","html":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/bk_tb_accounts.sql"}},"pairedItem":{"item":4},"index":4}